 let driverReceipt=null,driverTheme='light';
 function driverIcon(name){const paths={car:'<path d="m5 7 2-4h10l2 4 2 3v7H3v-7l2-3Z"/><path d="M5 7h14M6 12h2m8 0h2M5 17v3m14-3v3"/>',location:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',docs:'<path d="M6 3h8l4 4v14H6Z"/><path d="M14 3v5h5M9 12h6m-6 4h6"/>',home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 9h18m-6 5h6"/><circle cx="16" cy="14" r=".5"/>',shop:'<path d="M5 7h14l2 14H3L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',ride:'<path d="m3 17 6-6 4 4 8-10m-7 0h7v7"/>',inspection:'<rect x="5" y="5" width="14" height="16" rx="2"/><rect x="9" y="2" width="6" height="5" rx="1"/><path d="m8 14 3 3 5-6"/>',support:'<circle cx="12" cy="12" r="9"/><path d="M9.5 8.5a2.5 2.5 0 1 1 4 2c-1 .7-1.5 1-1.5 2.5m0 3h.01"/>',agenda:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-14 4h3m4 0h3"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',moon:'<path d="M20.8 13.2A9 9 0 0 1 10.8 3.1a9 9 0 1 0 10 10.1Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',back:'<path d="m14 6-6 6 6 6m-6-6h13"/>'};return `<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.more}</svg>`;}
 function driverProfile(){return ops.drivers.find(d=>d.id===activeDriverId)||ops.drivers[0];}
 function driverPersonal(){const personal=activeDriverId==='DRV-1'?ops.personal:(ops.driverProfiles||={})[activeDriverId]||=((ops.driverProfiles||={})[activeDriverId]={settings:{...D.defaults},offers:[],journeys:[]});personal.settings=D.validate(personal.settings);return personal;}
 function driverVehicle(){const d=driverProfile(),contract=K.contracts(ops,d.id).filter(c=>c.modelId==='rental'&&!['cancelled','refused'].includes(c.status)).at(-1);return M.vehicles(ops).find(v=>v.id===(d.vehicleId||d.nextVehicleId||contract?.vehicleId));}
 function driverCharges(){return ops.charges.filter(c=>c.driverId===activeDriverId).slice().sort((a,b)=>a.date.localeCompare(b.date));}
 function driverCharge(){return driverCharges().find(c=>c.status!=='paid'&&R.currentChargeBalance(ops,c)>0);}
 function driverPendingProof(charge){return charge&&ops.proofs.some(p=>p.chargeId===charge.id&&p.status==='pending');}
 function driverLeave(){try{inspectionSaveForm();}catch{toast('A vistoria ficou no último rascunho válido. Confira os campos quando voltar.');}}
 function driverNavigate(next){driverLeave();driverReceipt=null;driverPage=next;mode='driver';close();render();persist();window.scrollTo({top:0,behavior:'instant'});main.querySelector('[data-driver-title]')?.focus({preventScroll:true});}
 function driverDone(title,message,next='home',label='Voltar ao início'){driverReceipt={page:driverPage,title,message,next,label};close();render();persist();window.scrollTo({top:0,behavior:'instant'});main.querySelector('.driver-success h2')?.focus({preventScroll:true});}
 function driverMenuItem(key,title,description='',symbol='→'){return `<button type="button" class="driver-menu-item" data-driver-page="${key}"><span><strong>${title}</strong>${description?`<small>${description}</small>`:''}</span><span aria-hidden="true">${symbol}</span></button>`;}
 function driverOnboarding(){const d=driverProfile(),v=driverVehicle(),signed=K.hasSignedRental(ops,d.id,'2027-01-25',v?.id||null),inspected=v&&I.hasApprovedDelivery(ops,d.id,v.id),deposit=R.depositSummary(ops,d.id);return panel('Seu caminho até o carro',`<p class="caption">A RODAVOLT vai orientar você em cada etapa.</p><ol class="onboarding-steps">${[['Cadastro recebido',true],['Documentos conferidos',d.docs],['Contrato concluído no exemplo',signed],['Caução conferida',deposit.configured&&deposit.remaining<=0],['Vistoria de entrega aprovada',inspected],['Carro entregue',d.stage==='active']].map(([label,done])=>`<li class="${done?'done':''}"><span aria-hidden="true">${done?'✓':'○'}</span>${label}</li>`).join('')}</ol><div class="notice"><strong>Próximo passo</strong><br>${esc(d.note||'Aguarde a orientação da RODAVOLT.')}</div><div class="driver-menu-list gap">${driverMenuItem('docs','Ver meu contrato')}${driverMenuItem('inspection','Fazer vistoria')}${driverMenuItem('agenda','Ver meus compromissos')}${driverMenuItem('support','Pedir ajuda')}</div>`);}
 function driverDocumentsView(){const docs=K.driverDocuments(ops,activeDriverId);return `<section class="driver-process"><span>1 · Leia</span><span>2 · Assine fora do app</span><span>3 · Envie aqui</span></section><p class="caption">Se usar o GOV.BR, volte aqui com o PDF assinado. A equipe vai conferir o arquivo e a assinatura.</p>`+panel('Seus documentos',docs.length?docs.map(c=>`<article class="driver-document"><span class="driver-document-icon">${driverIcon('docs')}</span><h3>${esc(c.title)}</h3><p class="driver-doc-state">${['cancelled','refused','expired'].includes(c.status)?esc(c.statusLabel):c.status==='signed'?'Concluído no exemplo':c.driverRecorded?'Aguardando a RODAVOLT':c.status==='awaiting'||c.status==='partial'?'Precisa da sua atenção':esc(c.statusLabel)}</p><div class="actions">${btn('Ler contrato','driver-doc-preview','',`data-id="${c.id}"`)}${!['cancelled','refused','expired'].includes(c.status)?btn('Enviar contrato assinado','journey-contract','primary',`data-id="${c.id}"`):''}</div><details><summary>Datas e acompanhamento</summary>${row('Período',date(c.startDate)+' a '+date(c.endDate))}${row('Você',c.driverRecorded?'Registro de exemplo feito':'Ainda sem registro')}${row('RODAVOLT',c.companyRecorded?'Registro de exemplo feito':'Ainda sem registro')}<p class="caption">${esc(c.id)} · versão ${c.version}</p>${['awaiting','partial'].includes(c.status)&&!c.driverRecorded?btn('Simular assinatura no teste','driver-doc-sign','',`data-id="${c.id}"`):''}</details></article>`).join(''):'<div class="driver-empty"><span>'+driverIcon('docs')+'</span><h3>Seu contrato vai chegar aqui</h3><p>A RODAVOLT prepara o documento. Você lê com calma, assina e devolve pelo app.</p></div>')+'<p class="caption gap">Enviar um arquivo não confirma a validade da assinatura. A prévia usa documentos demonstrativos.</p>'; }
 function driverAppointmentTitle(e){return esc(e.title.replace(/ · COB-\d+$/,''));}
 function driverAgendaView(){const entries=K.driverAgendaItems(ops,activeDriverId).filter(e=>e.status!=='cancelled');return '<p class="caption">Horários da operação: '+esc(ops.agenda.timeZone||'America/Sao_Paulo')+'</p>'+panel('Para você não esquecer',entries.length?entries.map(e=>`<article class="driver-appointment"><p class="driver-date">${date(e.date)} · ${esc(e.time)}</p><h3>${driverAppointmentTitle(e)}</h3>${e.note?`<p>${esc(e.note)}</p>`:''}<p class="caption">${e.status==='done'?'Concluído':'A fazer'}</p></article>`).join(''):'<p>Nenhum compromisso por enquanto.</p>')+'<p class="caption gap">Nesta demonstração, confira os compromissos abrindo o app. Ainda não enviamos avisos no celular.</p>';}
 const driverNames={home:'Início',ride:'Conferir corrida',journey:'Anotar meu dia',wallet:'Meu aluguel',shop:'Minha lojinha',more:'Mais opções',care:'Cuidar do carro',inspection:'Fazer vistoria',docs:'Meu contrato',support:'Pedir ajuda',goals:'Quanto quero ganhar',onboarding:'Minha contratação',agenda:'Meus compromissos',benefits:'Meus benefícios',occurrences:'Ocorrências do carro'};
 function driverView(){const profile=driverProfile(),more=!['home','wallet','shop'].includes(driverPage);return `<div class="driver-layout"><section class="mobile-app" aria-label="Aplicativo do motorista"><header class="driver-app-head"><div class="driver-title-row"><div><p class="driver-greeting">${driverPage==='home'?'Olá,':'RODAVOLT · MOTORISTA'}</p><h1 tabindex="-1" data-driver-title>${driverPage==='home'?esc(profile.name.split(' ')[0]):driverNames[driverPage]}</h1></div><div class="driver-header-tools"><button type="button" class="driver-theme-button" data-action="driver-theme" aria-label="${driverTheme==='dark'?'Usar tema claro':'Usar tema escuro'}">${driverIcon(driverTheme==='dark'?'sun':'moon')}</button><button type="button" class="driver-profile-button" data-driver-page="more" aria-label="Ver mais opções">${driverIcon('user')}</button></div></div>${driverPage==='home'?'<p class="mobile-subtitle">Mais tranquilidade para rodar.</p>':'<button type="button" class="driver-back" data-driver-page="home">'+driverIcon('back')+'Voltar ao início</button>'}</header><div id="driver-body">${driverBody()}</div><details class="driver-demo-profile"><summary>Trocar perfil de demonstração</summary>${select('driverProfile','Pessoa do exemplo',activeDriverId,ops.drivers.map(d=>[d.id,d.name]),'data-driver-profile="true"')}<p class="caption">Só para testar. No app final, cada motorista terá seu próprio acesso.</p></details><nav class="driver-tabs" aria-label="Navegação do motorista">${[['home','Início'],['wallet','Aluguel'],['shop','Lojinha'],['more','Mais']].map(([key,label])=>`<button type="button" data-driver-page="${key}" ${key===driverPage||(key==='more'&&more)?'aria-current="page"':''}>${driverIcon({wallet:'wallet',shop:'shop',home:'home',more:'more'}[key])}<span>${label}</span></button>`).join('')}</nav></section></div>`;}
 function driverRentCard(detailed=false){const c=driverCharge(),credits=R.driverCredits(ops,activeDriverId),pending=driverPendingProof(c),forecast=!c?B.nextPlannedCharge(ops,activeDriverId):null;return `<section class="driver-rent-card"><p>${c?'Falta pagar nesta semana':forecast?'Próximo aluguel previsto':driverCharges().length?'Aluguel em dia':'Seu aluguel'}</p><strong>${c?cash(R.currentChargeBalance(ops,c)):forecast?cash(forecast.amount):driverCharges().length?cash(0):driverProfile().stage==='active'?'Sem cobrança emitida':'Ainda não começou'}</strong><p>${c?'Vence em '+date(c.date):forecast?'Vencimento previsto: '+date(forecast.due)+' · período de '+date(forecast.start)+' a '+date(forecast.end)+'. É uma previsão; nenhuma cobrança foi emitida ainda.':'Quando houver uma cobrança, ela aparecerá aqui.'}</p>${pending?'<p class="driver-rent-status">✓ Comprovante enviado. Vamos conferir.</p>':''}${c?.creditApplied?`<p class="driver-rent-status">${cash(c.creditApplied)} de desconto da lojinha já incluído.</p>`:''}${!detailed?'<button type="button" class="btn" data-driver-page="wallet">Ver meu aluguel →</button>':c&&!pending?btn('Já paguei · enviar comprovante de teste','proof','',`data-id="${c.id}"`):''}</section>${credits.available>0&&!detailed?`<button type="button" class="driver-credit-teaser" data-driver-page="wallet">Você tem ${cash(credits.available)} da lojinha para descontar <span aria-hidden="true">→</span></button>`:''}`;}
 function driverHome(){const d=driverProfile(),v=driverVehicle(),active=d.stage==='active',entries=K.driverAgendaItems(ops,activeDriverId).filter(e=>!['done','cancelled'].includes(e.status)).slice(0,1);if(d.stage==='closed')return driverClosureStatus(activeDriverId)+panel('Estamos aqui para ajudar','<p>Seu vínculo foi encerrado. Seus saldos, documentos e pedidos continuam disponíveis.</p><div class="driver-menu-list">'+driverMenuItem('wallet','Ver meus saldos')+driverMenuItem('docs','Meus documentos')+driverMenuItem('support','Pedir ajuda')+'</div>');if(!active)return driverOnboarding();const inventory=H.inventory(ops,activeDriverId),incoming=inventory.combos.some(c=>c.status==='sent'),low=inventory.products.filter(p=>p.available<=2&&!p.expired);return driverClosureStatus(activeDriverId)+`<section class="driver-car-strip"><span class="driver-car-icon">${driverIcon('car')}</span><div><strong>${esc(v?.model||'Seu carro RODAVOLT')}</strong><small>${esc(v?.plate||v?.id||'Vínculo em conferência')} · frota elétrica</small></div><button type="button" data-driver-page="care" aria-label="Ver meu carro">→</button></section><section class="driver-start"><div><span class="driver-eyebrow">ANTES DE SAIR</span><h2>Pronto para o seu dia?</h2>${journeyDriverStatus()}</div>${btn('Fazer check-in','journey-checkin','primary')}</section>${driverRentCard()}<div class="driver-section-label"><h2>O que vamos fazer?</h2><span>Um toque para começar</span></div><div class="driver-home-actions">${[['shop','Vender produto','Seu lucro, no seu bolso'],['inspection','Fazer vistoria','Fotos e itens do carro'],['ride','Conferir corrida','Saiba quanto vai sobrar'],['docs','Meus contratos','Leia e envie assinado']].map(([key,title,desc])=>`<button type="button" data-driver-page="${key}"><span class="driver-action-icon">${driverIcon(key)}</span><strong>${title}</strong><small>${desc}</small><span class="driver-action-arrow" aria-hidden="true">↗</span></button>`).join('')}</div>${incoming?'<button type="button" class="driver-credit-teaser" data-driver-page="shop">📦 Chegou um combo. Confira seus produtos →</button>':low.length?`<button type="button" class="driver-credit-teaser" data-driver-page="shop">Estoque baixo em ${low.length} produto(s). Ver minha lojinha →</button>`:''}<section class="driver-location-card"><span class="driver-action-icon">${driverIcon('location')}</span><div><strong>Compartilhar localização</strong><p>Você escolhe quando começar e quando parar.</p></div>${btn('Abrir','journey-location')}</section>${entries.map(e=>`<section class="driver-next"><p class="driver-eyebrow">SEU PRÓXIMO COMPROMISSO</p><strong>${driverAppointmentTitle(e)}</strong><p>${date(e.date)} · ${esc(e.time)}</p><button type="button" class="driver-text-button" data-driver-page="agenda">Ver compromisso →</button></section>`).join('')}<button type="button" class="driver-help-bar" data-driver-page="support">${driverIcon('support')}<span>Precisou? Fale com a RODAVOLT</span><span aria-hidden="true">→</span></button>`; }
 function driverSettlement(){const s=shopPending(activeDriverId);return `<details class="driver-detail-card"><summary>Como acertar minhas vendas?</summary>${row('Total vendido a conferir',cash(s.gross))}${row('Custo dos produtos',cash(s.cost))}${row('Seu lucro nessas vendas',cash(s.commission))}<p><strong>Para usar o lucro no aluguel:</strong> a RODAVOLT confere o recebimento do valor total das vendas. Só depois seu lucro vira crédito.</p><p><strong>Se você já ficou com o lucro em dinheiro:</strong> acerte o custo dos produtos que recebeu dos clientes. Esse lucro não vira desconto de novo.</p>${row('Custo a repassar das vendas recebidas por você',cash(s.remittance))}${row('Lucro a receber das vendas pagas à RODAVOLT',cash(s.payable))}<p class="caption">Combine o acerto com a RODAVOLT. Anotar a venda não faz um pagamento nem libera desconto sozinho.</p></details>`;}
 function driverCreditCard(){const s=R.driverCredits(ops,activeDriverId),c=driverCharge();return panel('Desconto da lojinha',`<p>Depois de conferir suas vendas, seu lucro pode diminuir o aluguel.</p><div class="driver-available"><span>Pronto para usar</span><strong>${cash(s.available)}</strong></div>${s.available>0&&c?btn('Usar no meu aluguel','driver-use-credit','primary',`data-id="${c.id}"`):s.available>0?'<p>Seu crédito está guardado para um próximo aluguel.</p>':'<p class="caption">Quando um acerto for conferido, o crédito aparece aqui.</p>'}<details><summary>Ver meu histórico de descontos</summary>${row('Lucro já conferido',cash(s.earned))}${row('Já descontado no aluguel',cash(s.applied))}${row('Já recebido em dinheiro',cash(s.paid))}<p class="caption">O lucro recebido em dinheiro não vira desconto de novo.</p></details>`);}
 function driverWallet(){const deposit=R.depositSummary(ops,activeDriverId),charges=driverCharges();return driverRentCard(true)+`<p class="caption">Enviar um comprovante de teste não confirma o pagamento. A RODAVOLT precisa conferir.</p><div class="gap">${driverCreditCard()}</div>${driverSettlement()}<details class="driver-detail-card"><summary>Ver meus aluguéis</summary>${charges.map(c=>row(date(c.date),cash(c.status==='paid'?c.amount:R.currentChargeBalance(ops,c)),c.status==='paid'?'Aluguel quitado · valor total':driverPendingProof(c)?'Comprovante em análise':'Falta pagar')+(c.creditApplied?`<p class="caption">Valor inicial ${cash(c.amount)} · desconto da lojinha ${cash(c.creditApplied)}</p>`:'')).join('')||'<p>Nenhum aluguel cobrado ainda.</p>'}</details><details class="driver-detail-card"><summary>Minha caução · dinheiro de garantia</summary><p>A caução é o dinheiro de garantia do carro. Ela fica separada do aluguel e do lucro da lojinha.</p>${row('Previsto no exemplo',cash(deposit.required))}${row('Recebido e conferido',cash(deposit.balance))}${row('Falta conferir',cash(deposit.remaining))}<p class="caption">A devolução segue seu contrato e a conferência das pendências.</p><button type="button" class="btn" data-driver-page="docs">Ver meu contrato</button></details>`;}
 function driverBenefitsSimple(){const pending=shopPending(activeDriverId).commission;return panel('A lojinha ajuda você',`<p>A RODAVOLT fornece os produtos. Todo o lucro da venda é seu, depois de descontar o custo do produto.</p>${row('Lucro ainda a conferir',cash(pending),'Ainda não é desconto disponível.')}<p class="caption">Você pode receber o lucro ou usar como desconto no aluguel, depois do acerto. O mesmo valor é usado uma vez.</p>`)+`<div class="gap">${driverCreditCard()}</div>${panel('Outros benefícios',`<article class="driver-benefit"><h3>App para suas finanças pessoais</h3><p>Estamos preparando esse benefício para ajudar você a cuidar do seu dinheiro.</p><span class="driver-doc-state">Em preparação</span></article><article class="driver-benefit"><h3>Novos apps e parcerias</h3><p>Vamos avisar quando houver algo disponível e explicar como participar.</p><span class="driver-doc-state">Planejados</span></article>`)}`;}
 function driverShop(){return '<section class="driver-shop-intro"><span class="driver-eyebrow">SUA RENDA EXTRA</span><h2>Produtos no carro.<br>Lucro para você.</h2><p>Escolha o produto, registre a venda e acompanhe seu ganho.</p></section>'+driverShopFlow();}
 function driverGoals(){const p=driverPersonal().settings,field=(key,label)=>input(key,label,p[key],`type="number" inputmode="decimal" min="${D.limits[key][0]}" max="${D.limits[key][1]}" step="${key==='workDays'?'1':'any'}" required`);return panel('Sua meta por dia',`<p>Quanto você quer que sobre depois de pagar os custos?</p><form id="goals-form"><div class="fields">${field('goalDay','Quero que sobre por dia · R$')}${field('energyPriceKWh','Preço da recarga · R$/kWh')}${field('consumptionKWh100Km','Consumo do carro · kWh/100 km')}${field('chargingLossPct','Perda estimada na recarga · %')}</div><details><summary>Meu aluguel e minha rotina</summary><div class="fields">${field('weeklyRent','Meu aluguel por semana · R$')}${field('workDays','Quantos dias trabalho por semana?')}${field('hoursDay','Quantas horas trabalho por dia?')}${field('plannedKmDay','Quantos km costumo rodar por dia?')}</div></details><details><summary>Ajustar ganho por km e por hora</summary><div class="fields">${field('minNetKm','Quero que sobre por km · R$')}${field('minNetHour','Quero que sobre por hora · R$')}${field('otherPerKm','Outros custos que eu pago por km · R$')}</div><p class="caption">Coloque apenas os custos que você paga. Não repita despesas que já estão no aluguel.</p></details><div class="form-actions"><button type="submit" class="btn primary">Salvar minha meta</button></div></form>`);}
 function driverJourney(){const personal=D.daySummary(driverPersonal().journeys,driverPersonal().settings);return panel('Como foi seu dia?',`<p>Anote o que entrou e o que você gastou.</p><form id="journey-form"><div class="fields">${input('date','Qual dia?','2027-01-25','type="date" required')}${input('amount','Quanto você recebeu? · R$',400,'type="number" inputmode="decimal" min="0" step=".01" required')}${input('energyKWh','Quantos kWh você carregou?',30,'type="number" inputmode="decimal" min="0" step="any" required')}${input('energyPriceKWh','Quanto pagou por kWh? · R$',driverPersonal().settings.energyPriceKWh??D.defaults.energyPriceKWh,'type="number" inputmode="decimal" min="0" step="any" required')}${input('other','Outras despesas do dia · R$',15,'type="number" inputmode="decimal" min="0" step=".01" required')}${input('km','Quantos km você rodou?',180,'type="number" inputmode="decimal" min="0" step="any" required')}${input('hours','Quantas horas trabalhou?',8,'type="number" inputmode="decimal" min="0" max="24" step="any" required')}</div><button type="submit" class="btn primary gap">Salvar meu dia</button><p class="caption">Salvar a mesma data de novo corrige aquele dia.</p></form>`)+`<details class="driver-detail-card"><summary>Ver o que sobrou e meu histórico</summary>${row('Total recebido',cash(personal.amount))}${row('Recargas e outras despesas',cash(personal.energyCost+personal.legacyFuelCost+personal.other))}${row('Parte do aluguel dos dias anotados',cash(personal.rent))}${row('Quanto sobrou',cash(personal.net),'',true)}${row('Sobrou por km',personal.netKm===null?'Sem registro':cash(personal.netKm))}${row('Sobrou por hora',personal.netHour===null?'Sem registro':cash(personal.netHour))}${driverPersonal().journeys.map(j=>row(date(j.date),cash(D.daySummary([j],driverPersonal().settings).net),num(j.km)+' km · '+num(j.hours)+' horas')).join('')}<p class="caption">O aluguel é dividido uma vez por dia anotado. Estes são seus registros pessoais.</p></details>`;}
 function driverCare(){const v=driverVehicle();if(!v)return panel('Aguardando seu carro','<p>Seu carro aparecerá aqui quando a RODAVOLT definir a entrega.</p>');return driverMaintenanceView(activeDriverId)+`<details class="driver-detail-card"><summary>Ver meu carro e a próxima revisão</summary>${row(esc(v.model),esc(v.id))}${row('Km no painel',num(v.km)+' km')}${row('Revisão com',v.nextKm===null?'Conferir data nos próximos cuidados':num(v.nextKm)+' km')}${row('Situação',v.status==='maintenance'?'Em manutenção':'Carro do seu vínculo')}<button type="button" class="btn" data-driver-page="inspection">Fazer vistoria</button></details>${panel('O que aconteceu com o carro?',`<form id="maintenance-request-form">${select('priority','Você consegue trabalhar?','normal',[['normal','Sim, mas o carro precisa de cuidado'],['urgent','Não, o carro está parado']])}<label class="field gap">Conte o que aconteceu<textarea name="note" required rows="4" maxlength="500" placeholder="Ex.: apareceu um alerta de bateria no painel."></textarea></label><button type="submit" class="btn primary gap">Pedir manutenção</button></form>`)}<details class="driver-detail-card"><summary>Ver meus pedidos e respostas</summary>${driverRequests('maintenance')}</details>`;}
 function driverSupport(){return panel('Como podemos ajudar?',`<form id="support-form">${select('subject','Sobre o que você quer falar?','Carro',[['Carro','Meu carro'],['Pagamento','Meu pagamento'],['Loja','Minha lojinha'],['Contrato','Meu contrato']])}<label class="field gap">Escreva sua mensagem<textarea name="note" required rows="4" maxlength="500" placeholder="Conte sua dúvida ou o que você precisa."></textarea></label><button type="submit" class="btn primary gap">Enviar pedido de ajuda</button></form><p class="caption">Neste teste, o pedido aparece no painel da gestão. Não envia mensagem fora daqui.</p>`)+`<details class="driver-detail-card"><summary>Ver meus pedidos e respostas</summary>${driverRequests('support')}</details>`;}
 function driverMore(){return `<div class="driver-connection-actions">${btn('Fazer check-in','journey-checkin','primary')}${btn('Minha localização','journey-location')}</div><section class="driver-more-group"><h2>Meu trabalho</h2><div class="driver-menu-list">${driverMenuItem('ride','Conferir uma corrida','Ver se o valor compensa')}${driverMenuItem('journey','Anotar meu dia','Ganhos e gastos do dia')}${driverMenuItem('goals','Quanto quero ganhar','Minha meta e meus custos')}</div></section><section class="driver-more-group"><h2>Meu carro</h2><div class="driver-menu-list">${driverMenuItem('inspection','Fazer vistoria','Conferir os itens e tirar fotos')}${driverMenuItem('care','Pedir manutenção','Avisar um problema no carro')}${driverMenuItem('occurrences','Ocorrências do carro','Ver e contar o que aconteceu')}${driverMenuItem('agenda','Meus compromissos','Ver datas e horários')}</div></section><section class="driver-more-group"><h2>Minha RODAVOLT</h2><div class="driver-menu-list">${driverMenuItem('benefits','Meus benefícios','Lucro da lojinha e novidades')}${driverMenuItem('docs','Meu contrato','Ler e acompanhar')}${!['active','closed'].includes(driverProfile().stage)?driverMenuItem('onboarding','Minha contratação','Acompanhar até receber o carro'):''}${driverMenuItem('support','Pedir ajuda','Ver também os pedidos e respostas')}</div></section>`;}
 function driverBody(){if(driverReceipt?.page===driverPage)return `<section class="driver-success" role="status"><span aria-hidden="true">✓</span><h2 tabindex="-1">${esc(driverReceipt.title)}</h2><p>${esc(driverReceipt.message)}</p><button type="button" class="btn primary" data-driver-page="${driverReceipt.next}">${esc(driverReceipt.label)}</button>${driverReceipt.next!=='home'?'<button type="button" class="btn" data-driver-page="home">Voltar ao início</button>':''}</section>`;const views={home:driverHome,wallet:driverWallet,shop:driverShop,more:driverMore,goals:driverGoals,journey:driverJourney,care:driverCare,occurrences:driverOccurrencesView,support:driverSupport,benefits:driverBenefitsSimple,onboarding:driverOnboarding,agenda:driverAgendaView,inspection:driverInspection,docs:driverDocumentsView,ride:rideView};return (views[driverPage]||driverHome)();}
 function driverRequests(type){const list=ops.requests.filter(r=>r.type===type&&(r.driverId||'DRV-1')===activeDriverId);return list.length?list.slice().reverse().map(r=>`<article class="driver-request"><strong>${r.status==='open'?'Pedido recebido':r.status==='answered'?'Respondido':r.status==='delivered'?'Entregue':'Estamos cuidando'}</strong><p>${esc(r.note)}</p>${r.reply?`<div class="notice"><strong>Resposta da RODAVOLT</strong><p>${esc(r.reply)}</p></div>`:'<p class="caption">Aguarde a resposta por aqui.</p>'}</article>`).join(''):'<p class="caption">Você ainda não fez um pedido por aqui.</p>';}
 function rideView(){rideResult=D.evaluate(ride,driverPersonal().settings);const field=(name,label)=>input(name,label,ride[name],`type="number" inputmode="decimal" min="0" step="any" required`);return `<p class="driver-intro">Vale a pena fazer esta corrida?</p><p>Use o valor que você vai receber do aplicativo.</p><form id="ride-form"><div class="fields">${field('amount','Quanto você vai receber? · R$')}${field('tripKm','Km da viagem com o passageiro')}${field('pickupKm','Km para buscar o passageiro')}${field('tripMin','Minutos da viagem')}${field('pickupMin','Minutos para buscar o passageiro')}</div><details><summary>Tem espera, retorno ou pedágio?</summary><div class="fields">${field('waitMin','Minutos de espera')}${field('returnKm','Km para voltar depois da viagem')}${field('returnMin','Minutos para voltar')}${field('toll','Pedágio que sai do meu bolso · R$')}</div></details><p id="ride-error" class="form-error" role="alert" hidden></p></form><div id="ride-result" aria-live="polite">${rideResultBody()}</div><div class="driver-decision actions gap">${btn('Vou aceitar','accept-ride','primary')}${btn('Vou recusar','reject-ride')}</div><p class="caption">Aqui você só anota sua decisão. Aceite ou recuse a corrida no aplicativo de transporte, com o carro parado.</p><button type="button" class="driver-text-button" data-driver-page="goals">Mudar minha meta e meus custos →</button><details class="driver-detail-card"><summary>Ver minhas decisões (${driverPersonal().offers.length})</summary>${driverPersonal().offers.slice().reverse().map(o=>row(o.choice==='accepted'?'Aceitei':'Recusei',cash(o.amount),cash(o.netKm)+' por km · '+cash(o.netHour)+' por hora, depois dos custos')).join('')||'<p>Nenhuma decisão anotada ainda.</p>'}</details>`;}
 function rideResultBody(){const r=rideResult;if(!r)return '<div class="notice amber">Confira os campos para calcular. A distância e o tempo precisam ser maiores que zero.</div>';return `<section class="ride-result ${r.meets?'':'negative'}"><h2 class="result-word">${r.meets?'Atinge sua meta':'Fica abaixo da sua meta'}</h2><p>Estimativa do que sobra para você</p><strong class="driver-ride-net">${cash(r.net)}</strong><div class="ride-metrics"><div><strong>${cash(r.netKm)}</strong><small>por km, após os custos</small></div><div><strong>${cash(r.netHour)}</strong><small>por hora, após os custos</small></div></div><p class="caption">Inclui ${num(r.km)} km e ${num(r.minutes)} minutos no total, contando a busca e o retorno informado.</p></section><details class="driver-detail-card"><summary>Como chegamos a esse valor?</summary>${row('Você recebe',cash(r.o.amount))}${row('Recarga estimada',cash(-r.energy.cost),'Consumo da viagem, perdas de recarga e seu preço em R$/kWh')}${row('Outros custos que você informou',cash(-r.variable))}${row('Parte do aluguel pelo tempo',cash(-r.rent))}${row('Pedágio do seu bolso',cash(-r.o.toll))}${row('Sobra estimada',cash(r.net),'',true)}${row('Para atingir sua meta, a oferta seria',cash(r.minimumOffer))}<p class="caption">Estimativa conforme sua meta, consumo, tempo e custos informados. O resultado real pode mudar.</p></details>`;}
 function updateRide(){const form=root.querySelector('#ride-form');if(!form)return;const values=Object.fromEntries(new FormData(form));try{for(const key of Object.keys(values)){if(String(values[key]).trim()==='')throw new RangeError('Preencha os campos da corrida para calcular.');values[key]=form.elements[key]?.dataset.currency?parseMoney(values[key]):Number(values[key]);if(!Number.isFinite(values[key]))throw new RangeError('Informe um valor válido.');}const calculated=D.evaluate(values,driverPersonal().settings);ride=values;rideResult=calculated;root.querySelector('#ride-error').hidden=true;}catch(error){rideResult=null;const element=root.querySelector('#ride-error');element.hidden=false;element.textContent=error.message;}root.querySelector('#ride-result').innerHTML=rideResultBody();}
 function driverAction(action,e){if(action==='driver-theme'){driverTheme=driverTheme==='dark'?'light':'dark';root.classList.toggle('driver-dark',driverTheme==='dark');e.setAttribute('aria-label',driverTheme==='dark'?'Usar tema claro':'Usar tema escuro');e.innerHTML=driverIcon(driverTheme==='dark'?'sun':'moon');persist();return true;}if(action.startsWith('driver-')&&driverNames[action.slice(7)]){driverNavigate(action.slice(7));return true;}
 if(action==='accept-ride'||action==='reject-ride'){updateRide();if(!rideResult)throw new RangeError('Confira os valores da corrida antes de anotar.');driverPersonal().offers.push({at:new Date().toISOString(),...ride,choice:action==='accept-ride'?'accepted':'rejected',net:rideResult.net,netKm:rideResult.netKm,netHour:rideResult.netHour,meets:rideResult.meets});driverDone('Decisão anotada',action==='accept-ride'?'Você anotou que vai aceitar. Agora faça sua escolha no aplicativo de transporte.':'Você anotou que vai recusar. Faça sua escolha no aplicativo de transporte.','ride','Conferir outra corrida');return true;}
 if(action==='driver-use-credit'){const charge=ops.charges.find(c=>c.id===e.dataset.id&&c.driverId===activeDriverId);if(!charge)throw new RangeError('Aluguel não encontrado para você.');const preview=R.applyAvailableCredit(structuredClone(ops),activeDriverId,charge.id);if(preview.amount<=0)throw new RangeError('Você ainda não tem desconto disponível para esse aluguel.');open('Usar meu desconto',`<form id="driver-credit-form"><input type="hidden" name="chargeId" value="${charge.id}">${row('Aluguel de '+date(charge.date),cash(R.currentChargeBalance(ops,charge)))}${row('Desconto da lojinha',cash(preview.amount))}${row('Depois, falta pagar',cash(preview.remaining),'',true)}<p>Quer usar seu lucro da lojinha para diminuir este aluguel?</p><button type="submit" class="btn primary gap">Sim, usar meu desconto</button><button type="button" class="btn gap" data-action="close">Agora não</button></form>`);return true;}
 if(action==='driver-doc-preview'){const doc=K.driverDocuments(ops,activeDriverId).find(c=>c.id===e.dataset.id);if(!doc)throw new RangeError('Este contrato não está no seu perfil.');open(doc.title,`<p class="notice amber">Contrato de exemplo. Precisa de revisão jurídica antes do uso real.</p>${doc.documents?.length?doc.documents.map((item,index)=>`<details class="gap"><summary>${index+1}. ${esc(item.title)}</summary><pre class="document-preview">${esc(item.body)}</pre></details>`).join(''):`<pre class="document-preview">${esc(doc.preview)}</pre>`}`);return true;}
 if(action==='driver-doc-sign'){const doc=K.driverDocuments(ops,activeDriverId).find(c=>c.id===e.dataset.id);if(!doc)throw new RangeError('Este contrato não está no seu perfil.');open('Testar minha assinatura',`<form id="driver-sign-form"><input type="hidden" name="documentId" value="${doc.id}"><p>Você pode testar o acompanhamento da assinatura de <strong>${esc(doc.title)}</strong>.</p><p class="notice amber">Isso não assina um contrato real.</p><label class="check"><input type="checkbox" name="read" required>Li o contrato de exemplo.</label><button type="submit" class="btn primary gap">Confirmar teste de assinatura</button></form>`);return true;}
 if(action==='proof'){if(!ops.charges.some(c=>c.id===e.dataset.id&&c.driverId===activeDriverId))throw new RangeError('Este aluguel não está no seu perfil.');M.proof(ops,e.dataset.id,'Envio ilustrativo pelo motorista · '+e.dataset.id);driverDone('Comprovante enviado no teste','Vamos conferir. O pagamento só aparece como confirmado depois da conferência.','wallet','Ver meu aluguel');return true;}return false;}
 function driverSubmit(form,f){const n=key=>Number(f.get(key));let handled=true;
 if(form.id==='goals-form'){const next={};for(const key of Object.keys(D.defaults))next[key]=n(key);driverPersonal().settings=D.validate(next);rideResult=D.evaluate(ride,next);driverDone('Meta salva','Suas próximas análises de corrida vão usar esses valores.');}
 else if(form.id==='journey-form'){M.saveJourney({personal:driverPersonal()},{date:String(f.get('date')),amount:n('amount'),energyKWh:n('energyKWh'),energyPriceKWh:n('energyPriceKWh'),other:n('other'),km:n('km'),hours:n('hours')});driverDone('Seu dia foi salvo','Os ganhos e gastos ficaram anotados. Você pode conferir o histórico ou corrigir esse dia depois.','journey','Ver meu dia');}
 else if(form.id==='driver-credit-form'){const result=R.applyAvailableCredit(ops,activeDriverId,String(f.get('chargeId')));driverDone(result.amount>0?'Desconto usado':'Desconto já conferido',`${cash(result.amount)} usado agora. Falta pagar ${cash(result.remaining)} neste aluguel.`,'wallet','Ver meu aluguel');}
 else if(form.id==='driver-sign-form'){if(!f.has('read'))throw new RangeError('Leia o contrato de exemplo antes de continuar.');if(!K.driverDocuments(ops,activeDriverId).some(c=>c.id===f.get('documentId')))throw new RangeError('Este contrato não está no seu perfil.');K.recordSignature(ops,String(f.get('documentId')),'driver');driverDone('Teste de assinatura registrado','A RODAVOLT poderá conferir o andamento. Nenhum contrato real foi assinado.','docs','Ver meu contrato');}
 else if(form.id==='maintenance-request-form'){M.request(ops,{type:'maintenance',driverId:activeDriverId,vehicleId:driverVehicle()?.id,priority:f.get('priority'),note:f.get('note')});driverDone('Pedido de manutenção recebido','Você pode ver a resposta em Cuidar do carro. Neste teste, o pedido já aparece para a gestão.','care','Acompanhar meu pedido');}
 else if(form.id==='stock-request-form'){const productId=f.get('productId'),p=ops.book.products.find(p=>p.id===productId);if(!p)throw new RangeError('Escolha o produto para pedir.');M.request(ops,{type:'stock',driverId:activeDriverId,vehicleId:driverVehicle()?.id,productId,qty:n('qty'),note:'Reposição de '+n('qty')+' × '+p.name});driverDone('Pedido de produtos recebido','A RODAVOLT vai conferir o pedido. O estoque só aumenta quando a entrega for registrada.','shop','Voltar para a lojinha');}
 else if(form.id==='support-form'){M.request(ops,{type:'support',driverId:activeDriverId,vehicleId:driverVehicle()?.id,subject:f.get('subject'),note:f.get('note')});driverDone('Pedido de ajuda recebido','Acompanhe a resposta em Pedir ajuda. Neste teste, o pedido já aparece para a gestão.','support','Acompanhar meu pedido');}
 else handled=false;return handled;}
